{
  "technical_and_design_decisions": [
    "Reactor upgrade (U1) will be done via Gradle dependency management across the Spring XD build, resolving API/deprecation incompatibilities introduced between the current Reactor version and 2.0.4, then validating with the existing test suite.",
    "XD-Admin HA (U2) will rely on ZooKeeper-based leader election already present in Spring XD; the Ambari stack/service definitions will be extended to install and manage multiple XD-Admin instances across cluster nodes.",
    "For the @EnableModule programming model (U3), an annotation-driven model will be implemented: classes annotated with @EnableModule get their channels auto-created by the framework; @Input and @Output mark the module's input/output channels, and framework infrastructure (a bean post-processor plus module-level binding support, conceptually aligned with spring-cloud-stream's @EnableBinding) creates the actual MessageChannel beans and channel adapters instead of the developer.",
    "Kryo work (U4) completes the existing codec optimizations (serializer registrations, PojoCodec tuning) and verifies them with serialization benchmarks before documenting usage guidelines.",
    "The 1.2.x CI migration (U5) targets Jenkins jobs running on EC2 instances, with the existing Gradle-based test suites parameterized to run reliably in that environment.",
    "U6 is treated as a time-boxed spike producing a prototype and findings document for resolving and installing module artifacts from a Maven repository via the XD CLI (artifactId-based resolution).",
    "The serialization codec (U7) will be extracted into a new Spring Integration module/artifact (e.g., spring-integration-codecs) with its own tests; Spring XD will be refactored to consume it as a Maven dependency and duplicate code removed.",
    "The Cloud Foundry deployer (U8) will implement the XD Admin module-deployment SPI as a CloudController-backed ModuleLauncher using the CF Java client, deploying modules as CF applications, consistent with the spring-cloud-data/spring-cloud-stream deployer approach and the XD-3194/XD-3229 spike deliverables.",
    "All code changes follow the existing Spring XD/Spring Integration coding conventions, include unit and integration tests, and are delivered with updated reference documentation where applicable."
  ],
  "assumptions": [
    "One developer (the author) performs all work; estimates are personal effort in workdays (8 hours/day), not elapsed calendar time.",
    "The developer is experienced with Spring XD, Spring Integration, Gradle, Ambari, EC2, and Cloud Foundry, and has access to the existing codebases, CI systems, EC2 account, and a Cloud Foundry test environment.",
    "The referenced spike deliverables (XD-3194, XD-3229) and related repositories are available as design input for U8.",
    "The increment targets the Spring XD 1.2.x/1.3-era codebase on Java 8 with Gradle builds, consistent with Reactor 2.0.x compatibility.",
    "U6 is a research/prototyping spike only; production-hardened module installation from Maven is out of scope for this increment.",
    "Peer code review, release management beyond basic version coordination, and PM/QA overhead are excluded from the estimates.",
    "Existing test coverage is adequate to serve as a regression safety net for refactoring and upgrade work."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Increment setup and requirements analysis",
      "activity_description": "Review all eight user stories, set up/update local development environments for the Spring XD, Spring Integration, and related repositories, and confirm branching/versioning strategy for the increment.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A2",
      "activity_name": "U1 - Upgrade Reactor to 2.0.4",
      "activity_description": "Bump Reactor to 2.0.4 in Gradle dependency management, resolve compilation errors and deprecated/changed APIs across Spring XD modules that consume Reactor.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A3",
      "activity_name": "U1 - Reactor upgrade regression verification",
      "activity_description": "Run affected unit/integration test suites, verify stream processing and transport behavior against Reactor 2.0.4, and confirm CI passes.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A4",
      "activity_name": "U2 - Ambari multi-instance XD-Admin configuration",
      "activity_description": "Extend Ambari stack/service definitions, scripts, and configuration templates to install, configure, and manage multiple XD-Admin server instances for the Spring XD cluster.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A5",
      "activity_name": "U2 - HA failover testing and documentation",
      "activity_description": "Deploy a multi-admin cluster via Ambari, verify ZooKeeper-based leader election and failover behavior (admin kill/restart scenarios), and document the HA setup steps.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A6",
      "activity_name": "U3 - Design @EnableModule annotation model",
      "activity_description": "Design the @EnableModule, @Input, and @Output annotations and the binding SPI: lifecycle, how annotated classes are detected, and how channels/adapters are declared and auto-created.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A7",
      "activity_name": "U3 - Implement annotation-driven channel creation",
      "activity_description": "Implement the framework infrastructure (annotation processing/bean post-processing and module binding support) that creates MessageChannel beans and channel adapters for @EnableModule classes based on @Input/@Output declarations.",
      "most_likely_effort": 5
    },
    {
      "activity_id": "A8",
      "activity_name": "U3 - Tests for annotation-driven modules",
      "activity_description": "Write unit and integration tests covering module creation via annotations, channel wiring, channel adapter creation, and error cases (missing/duplicate channels).",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A9",
      "activity_name": "U3 - Documentation and sample module updates",
      "activity_description": "Update reference documentation and convert/provide sample modules demonstrating the @EnableModule programming model.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A10",
      "activity_name": "U4 - Complete Kryo codec optimizations",
      "activity_description": "Finish the remaining Kryo optimization changes (serializer registrations, PojoCodec tuning, edge-case handling) and validate with serialization benchmarks and tests.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A11",
      "activity_name": "U4 - Kryo guidelines documentation",
      "activity_description": "Write and polish developer-facing guidelines for using and extending the Kryo serialization support (custom serializers, registration, performance notes).",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A12",
      "activity_name": "U5 - Provision EC2 CI infrastructure for 1.2.x",
      "activity_description": "Provision and configure EC2 instances/images and Jenkins master/agents needed to host the 1.2.x branch CI builds.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A13",
      "activity_name": "U5 - Migrate and stabilize CI suites on EC2",
      "activity_description": "Migrate the 1.2.x CI jobs/test suites to the EC2 infrastructure, fix environment-specific failures (ports, filesystem, timing), and verify repeatable green runs.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A14",
      "activity_name": "U6 - Spike: install XD modules from Maven repo via CLI",
      "activity_description": "Brainstorm and investigate techniques for resolving a module by artifactId from the XD CLI, downloading it from a Maven repository, and installing it into a running Spring XD runtime; build a small prototype and document findings/recommendation.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A15",
      "activity_name": "U7 - Extract serialization codec into Spring Integration",
      "activity_description": "Move the serialization codec code from the Spring XD repository into a new Spring Integration module/artifact, including package refactoring, build setup, and ported/new unit tests.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A16",
      "activity_name": "U7 - Refactor Spring XD to consume codec dependency",
      "activity_description": "Remove the duplicated codec code from Spring XD, add the Maven dependency on the new SI artifact, adapt imports/configuration, and run Spring XD serialization-related test suites.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A17",
      "activity_name": "U8 - Design CloudController-based Admin SPI deployer",
      "activity_description": "Design the ModuleLauncher-based implementation of the XD Admin module deployment SPI backed by the Cloud Foundry Cloud Controller client, informed by the XD-3194/XD-3229 spike deliverables and the spring-cloud-data/spring-cloud-stream deployer approach.",
      "most_likely_effort": 2
    },
    {
      "activity_id": "A18",
      "activity_name": "U8 - Implement CloudController ModuleLauncher",
      "activity_description": "Implement deploy/undeploy/status/scale operations for XD modules as Cloud Foundry applications via the Cloud Controller API, including module packaging resolution, environment property mapping, and error handling.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A19",
      "activity_name": "U8 - End-to-end pipeline testing on Cloud Foundry",
      "activity_description": "Deploy representative data pipeline use cases (e.g., stream with source/processor/sink) on Cloud Foundry using the new SPI implementation and verify runtime behavior, logging, and redeploy cycles.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A20",
      "activity_name": "U8 - Documentation for CF-based deployment",
      "activity_description": "Document how to configure and run XD Admin with the CloudController-based SPI implementation on Cloud Foundry, including prerequisites and limitations.",
      "most_likely_effort": 1
    },
    {
      "activity_id": "A21",
      "activity_name": "Cross-cutting integration and regression hardening",
      "activity_description": "Run the full Spring XD build and test suites across all changes (Reactor upgrade, codec move, annotation model, HA, CF deployer), fix integration issues, and harden the increment.",
      "most_likely_effort": 3
    },
    {
      "activity_id": "A22",
      "activity_name": "Build and dependency version coordination",
      "activity_description": "Coordinate dependency versions across Spring XD and Spring Integration (codec artifact, Reactor), finalize build metadata, and prepare the increment for merge/release.",
      "most_likely_effort": 1
    }
  ],
  "reported_total": {
    "most_likely_effort": 55
  }
}
